const types=[['草ブロック',0x70a84d],['土',0x91643d],['石',0x929a94],['木',0x9a714a],['葉',0x4e8a4d],['砂',0xd9ca91],['レンガ',0xaf6959],['木材',0xc8a274]];
const world=new Map(), key=(x,y,z)=>`${x},${y},${z}`;let meshes=[];const geo=new THREE.BoxGeometry(1,1,1);const mats=types.map(t=>new THREE.MeshLambertMaterial({color:t[1]}));
