let yaw=0,pitch=-.15;document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement){yaw-=e.movementX*.002;pitch=Math.max(-1.5,Math.min(1.5,pitch-e.movementY*.002))}});const keys={};document.addEventListener('keydown',e=>{keys[e.code]=true;if(/^Digit[1-8]$/.test(e.code))select(+e.code.slice(-1)-1);if(e.code==='Space')e.preventDefault()});document.addEventListener('keyup',e=>keys[e.code]=false);addEventListener('wheel',e=>select(selected+Math.sign(e.deltaY)),{passive:true});addEventListener('contextmenu',e=>e.preventDefault());
const ray=new THREE.Raycaster();function target(){ray.setFromCamera(new THREE.Vector2(0,0),camera);ray.far=7;let hit=ray.intersectObjects(meshes)[0];if(!hit)return;let p=hit.object.userData.positions[hit.instanceId],n=hit.face.normal;return {p,n}}function editBlock(button){if(!playing)return;let hit=target();if(!hit)return;let [x,y,z]=hit.p;if(button===0){multi.edit(key(x,y,z),null)}else if(button===2){x+=hit.n.x;y+=hit.n.y;z+=hit.n.z;if(Math.abs(x-pos.x)<.8&&Math.abs(z-pos.z)<.8&&Math.abs(y-(pos.y-.7))<1.3)return;multi.edit(key(x,y,z),selected)}}
renderer.domElement.addEventListener('mousedown',e=>{if(document.pointerLockElement===renderer.domElement)editBlock(e.button)});
let joyX=0,joyY=0,joyPointer=null,lookPointer=null,lastX=0,lastY=0,touchJump=false;const joystick=document.querySelector('#joystick'),stick=document.querySelector('#stick');
function updateJoy(e){const r=joystick.getBoundingClientRect(),radius=r.width*.38;let x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2),length=Math.hypot(x,y);if(length>radius){x=x/length*radius;y=y/length*radius}joyX=x/radius;joyY=y/radius;stick.style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`}
