renderer.domElement.addEventListener('pointerdown',e=>{if(!touchActive||!playing||e.pointerType==='mouse'||lookPointer!==null)return;e.preventDefault();lookPointer=e.pointerId;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerId!==lookPointer)return;yaw-=(e.clientX-lastX)*.005;pitch=Math.max(-1.5,Math.min(1.5,pitch-(e.clientY-lastY)*.005));lastX=e.clientX;lastY=e.clientY});function releaseLook(e){if(e.pointerId===lookPointer)lookPointer=null}renderer.domElement.addEventListener('pointerup',releaseLook);renderer.domElement.addEventListener('pointercancel',releaseLook);renderer.domElement.addEventListener('lostpointercapture',releaseLook);
