let saveTimer,mode='solo';function saveWorld(){try{localStorage.setItem('block-field-world',JSON.stringify([...world]));return true}catch{message('保存できませんでした');return false}}
const peerAvatar=new THREE.Group();const peerBody=new THREE.Mesh(new THREE.BoxGeometry(.6,.85,.35),new THREE.MeshLambertMaterial({color:0x3886b6}));peerBody.position.y=-1.05;const peerHead=new THREE.Mesh(new THREE.BoxGeometry(.48,.48,.48),new THREE.MeshLambertMaterial({color:0xf1c79d}));peerHead.position.y=-.38;peerAvatar.add(peerBody,peerHead);peerAvatar.visible=false;scene.add(peerAvatar);
